import csv, json, collections
from fractions import Fraction as F
def rd(p): return list(csv.DictReader(open(p)))
plan={r['run_id']:r for r in rd('plan.csv')}
launch=rd('launch_log.csv'); 
L=collections.OrderedDict()
for r in launch: L.setdefault(r['run_id'],r)
ev=rd('eval_results.csv')
E={}
for r in ev:
    v=F(r['pass_rate'])
    if r['run_id'] in E and E[r['run_id']]!=v: print("CONFLICT eval",r)
    E[r['run_id']]=v
ret=rd('retention_log.csv')
rt=rd('runtime.csv'); RT={}
for r in rt: RT.setdefault(r['run_id'],r['finished_at'])
dig={r['date']:(int(r['n_runs']),F(r['sum_pass_rate'])) for r in rd('daily_digest.csv')}
suites=json.load(open('suites.json')); pol=json.load(open('retention_policy.json'))
